import{_ as a,o as n,c as e,am as p}from"./chunks/framework._FJXuPhs.js";const h=JSON.parse('{"title":"Kubernetes","description":"","frontmatter":{"title":"Kubernetes","excerpt":"Kubernetes","date":"2024-01-22 09:53:58","updated":"2024-01-22 09:53:58"},"headers":[],"relativePath":"部署&工具/Java 知识体系-容器部署/Kubernetes.md","filePath":"部署&工具/Java 知识体系-容器部署/Kubernetes.md","lastUpdated":null}'),l={name:"部署&工具/Java 知识体系-容器部署/Kubernetes.md"};function t(i,s,c,o,d,r){return n(),e("div",null,[...s[0]||(s[0]=[p(`<blockquote><p>复习一下 docker</p></blockquote><p>docker → 进程隔离 ；操作系统层虚拟化（同一个操作系统下隔离软件环境）</p><p>镜像 image → 容器 Container → 仓库</p><p>查看容器占用资源：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docker status</span></span></code></pre></div><p>微服务：负载均衡（多节点，实现高可用，平稳过度）</p><p>将一个整体的服务拆分为多个微服务</p><p>考虑的内容：日志收集（多节点），服务监控，资源服务器分配，判断服务的前置依赖</p><p>上面这些考虑的内容可以通过 K8s 来进行处理。</p><ul><li>K8s: 容器编排系统，用于管理和扩展大规模的容器部署</li><li>Portainer: 容器管理工具，提供了一个易于使用的界面来管理 Docker 和 Kubernetes 资源。</li></ul><h3 id="_1、k8s-是什么" tabindex="-1">1、K8s 是什么 <a class="header-anchor" href="#_1、k8s-是什么" aria-label="Permalink to &quot;1、K8s 是什么&quot;">​</a></h3><p>Kubernetes（也称 k8s 或 “kube”）是一个开源的容器编排平台，可以自动化在部署、管理和扩展容器化应用过程中涉及的许多手动操作</p><p>参考</p><ul><li><a href="https://www.kubernetes.org.cn/k8s" target="_blank" rel="noreferrer">https://www.kubernetes.org.cn/k8s</a></li><li><a href="https://kubernetes.io/zh-cn/docs/home/" target="_blank" rel="noreferrer">https://kubernetes.io/zh-cn/docs/home/</a></li></ul><p>核心特性：</p><ul><li><strong>服务发现和负载均衡</strong>：Kubernetes可以自动发现应用服务，并通过一个统一的服务名进行访问，如果服务的容器出现故障，可以自动重新路由到其他健康容器。</li><li><strong>存储编排</strong>：自动挂载所选存储系统，无论是本地存储、公共云提供商的存储，还是网络存储系统。</li><li><strong>自动部署和回滚</strong>：可以描述应用的期望状态，Kubernetes可以自动将实际状态改变为期望状态。如果有任何变更导致错误，Kubernetes可以回滚到之前的状态。</li><li><strong>自动完成容器编排</strong>：基于资源消耗自动放置容器到节点，考虑资源需求和约束，而不是手动选择运行的节点。</li><li><strong>自我修复</strong>：自动重启失败的容器，替换和杀掉不响应用户定义的健康检查的容器，直到应用正常运行。</li><li><strong>密钥与配置管理</strong>：部署和更新密钥和应用配置，不需要改变容器镜像，避免将密钥存储在容器镜像中。</li></ul><h3 id="_2、k8s-如何使用" tabindex="-1">2、K8s 如何使用 <a class="header-anchor" href="#_2、k8s-如何使用" aria-label="Permalink to &quot;2、K8s 如何使用&quot;">​</a></h3><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240322095336.png" alt="image.png"></p><blockquote><p>控制平面组件</p></blockquote><p>控制平面（Master节点）包含了以下几个核心组件，它们负责整个集群的管理和协调工作：</p><ul><li><strong>API Server</strong>（kube-apiserver）：作为集群的前端，它提供了Kubernetes API服务，是用户、外部应用和集群内部各组件交互的接口。</li><li><strong>Scheduler</strong>（kube-scheduler）：负责调度决策，选择哪个节点来运行未运行的Pod。它根据资源需求、硬件/软件/策略约束、亲和性和反亲和性规范、数据局部性、工作负载间干扰和截止日期等多种因素做出决策。</li><li><strong>Controller Manager</strong>（kube-controller-manager）：管理控制器进程，这些控制器包括节点控制器、副本控制器、端点控制器、服务帐号和令牌控制器等。控制器通常负责集群的状态管理，确保应用的当前状态与用户声明的期望状态一致。</li><li><strong>ETCD</strong>：是一个一致性、高可用的键值存储数据库，用于保存所有集群数据，是整个集群的“真实来源”。</li></ul><blockquote><p>节点组件</p></blockquote><p>节点（Node节点）通常是物理机或虚拟机，运行着容器化应用，它包含了以下几个关键组件：</p><ul><li><strong>Kubelet</strong>：负责管理Pod和它们的容器、镜像、卷等，包括启动、停止容器应用，维护容器的运行状态等。</li><li><strong>Kube Proxy</strong>（kube-proxy）：是网络代理，运行在每个节点上，负责服务发现和负载均衡，它处理节点上的网络路由，并实施部分网络策略。</li><li><strong>Container Runtime</strong>：负责运行容器，例如Docker、containerd等。</li></ul><p>Pod</p><ul><li><strong>Pod</strong>：Pod是Kubernetes中的基本部署单元，它是一个或一组容器的集合，共享存储和网络，运行在同一节点上。</li></ul><blockquote><p>工作流程</p></blockquote><p>工作流程通常是这样的：</p><ol><li>用户或自动化系统使用kubectl（或其他客户端）向API Server发送指令。</li><li>API Server将配置信息存储在ETCD中。</li><li>Scheduler监听API Server，寻找没有分配节点的新Pod，并选择一个节点来运行这个Pod。</li><li>一旦Pod被指派到一个节点，对应节点上的Kubelet负责初始化容器环境，启动容器，并保持容器的运行状态。</li><li>Kube Proxy负责处理该节点上Pod的网络通信。</li></ol><hr><p>K8s 是一个容器编排调工具，能够进行自动资源调度和服务发现与负载均衡</p><p>资源调度</p><p>容器编排系统能够根据容器的资源需求（如CPU、内存、存储等），自动选择最合适的主机节点来部署容器。这通常涉及复杂的决策过程，可能包括：</p><ul><li><strong>负载均衡</strong>：在多个主机间分配容器，以保持负载均衡。</li><li><strong>高可用性</strong>：确保应用组件跨多个故障域部署，以提高容错能力。</li><li><strong>资源限制</strong>：为每个容器设置资源限制，避免单个容器耗尽所有主机资源。</li></ul><p>服务发现与负载均衡</p><p>容器启动和停止时，它们的IP地址和端口是动态分配的。容器编排系统需要提供服务发现机制，以便容器和服务可以互相发现和通信。同时，它可以实现内部负载均衡，将流量分发到多个容器实例</p><hr><h3 id="_3、灰度发布" tabindex="-1">3、灰度发布 <a class="header-anchor" href="#_3、灰度发布" aria-label="Permalink to &quot;3、灰度发布&quot;">​</a></h3><p>灰度发布（也称为金丝雀发布或渐进式发布）是软件发布的一种策略，其中新版本的软件逐步替换旧版本，这样新的变更只影响一部分用户。这个过程允许开发和运维团队监控新版本的表现，而不会影响所有用户。</p><p>灰度发布的关键目的是减少由于新版本引入的风险。通过先对一小部分用户进行发布，可以在不干扰所有用户的情况下测试新版本在生产环境中的表现。</p><p>这个灰度发布可以通过 k8s 的部署策略去做到</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240322102017.png" alt="image.png"></p><blockquote><p>推荐参考</p></blockquote><p><a href="https://www.kancloud.cn/zatko/kubernetes_k8s/2290695" target="_blank" rel="noreferrer">https://www.kancloud.cn/zatko/kubernetes_k8s/2290695</a></p><h3 id="部署使用-🚩" tabindex="-1">部署使用 🚩 <a class="header-anchor" href="#部署使用-🚩" aria-label="Permalink to &quot;部署使用  🚩&quot;">​</a></h3><h4 id="网络连通" tabindex="-1">网络连通 <a class="header-anchor" href="#网络连通" aria-label="Permalink to &quot;网络连通&quot;">​</a></h4><p>这里使用一下虚拟机完成以下相关功能</p><p>虚拟机 开三个机器，master 双核4G,两个node双核8G</p><p>这里使用的虚拟机是 Virtual Box</p><p>建议设置以下 热键 → 虚拟电脑 → 主机组合键 → 设置为 Ctrl + Alt</p><p>密码设置 root/root</p><p>创建用户 luoqi/123456 🕷</p><p>需要后面看一下，目前是虚拟机不能获取到 ip 地址，且执行 sudo 命令不起效果</p><p>不用管之前的操作方式，选择新增虚拟机的操作，然后在网络与主机名初始配置这里选择打开</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240411153119.png" alt="image.png"></p><p>正常来说，按照这种初始化配置是可以进行在虚拟机中 Ping 通外网的</p><p>进行网络配置：选择网卡2，进行选择“仅主机(Host-Only) 网络”</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240411153802.png" alt="image.png"></p><p>再次启动虚拟机后，进入到 终端，输入 <code>ip addr</code></p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240411155412.png" alt="image.png"></p><p>然后就可以使用 shell 工具进行连接操作。</p><p>按照同样的方式创建两个从节点👇</p><p>复制操作（选择复制一下主节点），复制主节点虚拟机到两个子节点。</p><h4 id="部署操作" tabindex="-1">部署操作 <a class="header-anchor" href="#部署操作" aria-label="Permalink to &quot;部署操作&quot;">​</a></h4><p>这里选用了 kubeadm 工具去进行集群环境下的部署。</p><p>部署 Kubernetes 集群通常包括设置一个或多个 master 节点和多个 worker 节点。</p><blockquote><p>系统要求</p></blockquote><ul><li>一定数量的机器（物理机或虚拟机），至少 2GB RAM，2 CPUs。</li><li>系统支持的操作系统（如 Ubuntu, CentOS）。</li><li>禁用 Swap。</li><li>集群中所有机器之间网络互通</li><li>可以访问外网，需要拉取镜像</li></ul><p>大概的一些步骤</p><ul><li>1、环境准备</li><li>2、安装 kubeadm, kubelet 和 kubectl （工具安装）</li><li>3、初始化集群</li><li>4、设置 kubectl，配置当前用户使用 kubectl 连接到 Kubernetes 集群</li><li>5、选择并部署一个 Pod 网络到集群中，加入工作节点，进行验证操作。</li></ul><hr><p>参考这套： <a href="https://cloud.tencent.com/developer/article/1674040" target="_blank" rel="noreferrer">https://cloud.tencent.com/developer/article/1674040</a></p><p>视频参考： <a href="https://www.bilibili.com/video/BV1LC4y1g7wz" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1LC4y1g7wz</a></p><h5 id="准备环境" tabindex="-1">准备环境 <a class="header-anchor" href="#准备环境" aria-label="Permalink to &quot;准备环境&quot;">​</a></h5><p>【环境角色】</p><p>master：192.168.56.101</p><p>node1：192.168.56.102</p><p>node2：192.168.56.103</p><p>三个节点都选择无界面启动（虚拟机）</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>关闭防火墙：</span></span>
<span class="line"><span>$ systemctl stop firewalld</span></span>
<span class="line"><span>$ systemctl disable firewalld</span></span>
<span class="line"><span></span></span>
<span class="line"><span>关闭selinux：</span></span>
<span class="line"><span>$ sed -i &#39;s/enforcing/disabled/&#39; /etc/selinux/config  # 永久</span></span>
<span class="line"><span>#这里设置永久的话，是需要重启后才能失效，设置临时是为了保证这一次不重启也先临时关闭下 selinux</span></span>
<span class="line"><span>$ setenforce 0  # 临时</span></span>
<span class="line"><span></span></span>
<span class="line"><span>关闭swap：</span></span>
<span class="line"><span>$ swapoff -a  # 临时</span></span>
<span class="line"><span>$ vim /etc/fstab  # 永久</span></span>
<span class="line"><span></span></span>
<span class="line"><span>设置主机名：</span></span>
<span class="line"><span>$ hostnamectl set-hostname &lt;hostname&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>在master添加hosts：</span></span>
<span class="line"><span>#建议在所有节点上操作</span></span>
<span class="line"><span>$ cat &gt;&gt; /etc/hosts &lt;&lt; EOF</span></span>
<span class="line"><span>192.168.56.101 k8s-master</span></span>
<span class="line"><span>192.168.56.102 k8s-node1</span></span>
<span class="line"><span>192.168.56.103 k8s-node2</span></span>
<span class="line"><span>EOF</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#每个节点都进行操作，创建或覆盖一个名为 \`k8s.conf\` 的文件在 \`/etc/sysctl.d/\` 目录下</span></span>
<span class="line"><span>#确保经过 Linux 网桥的 IPv4 和 IPv6 流量都被传递到 \`iptables\`（和 \`ip6tables\`）的链中进行处理</span></span>
<span class="line"><span>#将桥接的IPv4流量传递到iptables的链：</span></span>
<span class="line"><span>$ cat &gt; /etc/sysctl.d/k8s.conf &lt;&lt; EOF</span></span>
<span class="line"><span>net.bridge.bridge-nf-call-ip6tables = 1</span></span>
<span class="line"><span>net.bridge.bridge-nf-call-iptables = 1</span></span>
<span class="line"><span>EOF</span></span>
<span class="line"><span>$ sysctl --system  # 生效</span></span>
<span class="line"><span></span></span>
<span class="line"><span>时间同步：</span></span>
<span class="line"><span>$ yum install ntpdate -y</span></span>
<span class="line"><span>$ ntpdate time.windows.com</span></span></code></pre></div><p>操作说明</p><ul><li>关闭防火墙：Kubernetes 需要在集群的各个节点之间进行网络通信，防火墙可能会阻止或限制这些通信。关闭防火墙可以简化网络配置和故障排除过程，避免通信被不必要地阻断。</li><li>关闭 SELinux：SELinux（Security-Enhanced Linux）可以增强系统的安全性，但它也可能与 Kubernetes 的一些组件不兼容，特别是涉及到文件系统权限和网络访问。禁用 SELinux 可以减少权限问题，特别是在 Pod 之间共享数据时。</li><li>关闭swap：Kubernetes 官方推荐在运行 kubelet 的机器上禁用 swap 空间。这是因为 Kubernetes 的调度器将考虑节点的内存使用情况来安排 Pod，启用 swap 空间会使内存管理变得复杂，可能会导致调度和资源限制的问题。</li><li>设置主机名：为每个节点设置一个独一无二的主机名有助于节点间的识别和管理。在管理和维护集群时，能够通过主机名快速识别具体节点。</li><li>在 master 添加 hosts：这个操作是为了简化节点间的网络通信，尤其是在 DNS 服务不稳定或不可用的情况下。通过在 <code>/etc/hosts</code> 文件中静态定义 IP 地址和主机名的映射，可以保证即使在 DNS 解析问题发生时，节点间的通信也不会受到影响。</li><li>将桥接的 IPv4 流量传递到 iptables 的链：这些设置确保所有从 Linux bridges 传递的流量都会被 iptables 的规则所处理。这对于网络插件（如 Calico 或 Flannel）来确保 Pod 网络的正常工作至关重要。</li><li>时间同步：所有节点的时间同步是非常重要的，特别是在分布式系统中，时间偏差可能导致日志、事件处理和其他时间敏感的操作出现问题。使用 <code>ntpdate</code> 确保节点时间的一致性，有助于维护集群的稳定性和可靠性。</li></ul><hr><p>使用 <code>vim</code> 打开 <code>/etc/fstab</code> 文件后，你会看到类似下面的内容</p><p>在对应的 含有 swap 的行，添加 # 进行注释，保存退出</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240414140244.png" alt="image.png"></p><p>设置主机名</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hostnamectl set-hostname k8s-master</span></span>
<span class="line"><span></span></span>
<span class="line"><span>hostnamectl set-hostname k8s-node1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>hostnamectl set-hostname k8s-node2</span></span></code></pre></div><h5 id="工具安装" tabindex="-1">工具安装 <a class="header-anchor" href="#工具安装" aria-label="Permalink to &quot;工具安装&quot;">​</a></h5><p>安装 docker</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ wget https://mirrors.aliyun.com/docker-ce/linux/centos/docker-ce.repo -O /etc/yum.repos.d/docker-ce.repo</span></span>
<span class="line"><span>$ yum -y install docker-ce-18.06.1.ce-3.el7</span></span>
<span class="line"><span>$ systemctl enable docker &amp;&amp; systemctl start docker</span></span>
<span class="line"><span>$ docker --version</span></span>
<span class="line"><span>Docker version 18.06.1-ce, build e68fc7a</span></span></code></pre></div><p>配置镜像仓库地址</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ cat &gt; /etc/docker/daemon.json &lt;&lt; EOF</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  &quot;registry-mirrors&quot;: [&quot;https://7iwp6tq0.mirror.aliyuncs.com&quot;]</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>EOF</span></span></code></pre></div><p>添加 k8s YUM 源</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ cat &gt; /etc/yum.repos.d/kubernetes.repo &lt;&lt; EOF</span></span>
<span class="line"><span>[kubernetes]</span></span>
<span class="line"><span>name=Kubernetes</span></span>
<span class="line"><span>baseurl=https://mirrors.aliyun.com/kubernetes/yum/repos/kubernetes-el7-x86_64</span></span>
<span class="line"><span>enabled=1</span></span>
<span class="line"><span>gpgcheck=0</span></span>
<span class="line"><span>repo_gpgcheck=0</span></span>
<span class="line"><span>gpgkey=https://mirrors.aliyun.com/kubernetes/yum/doc/yum-key.gpg https://mirrors.aliyun.com/kubernetes/yum/doc/rpm-package-key.gpg</span></span>
<span class="line"><span>EOF</span></span></code></pre></div><p>安装kubeadm，kubelet和kubectl</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>yum install -y kubelet-1.18.0 kubeadm-1.18.0 kubectl-1.18.0</span></span>
<span class="line"><span>systemctl enable kubelet</span></span></code></pre></div><p>TIPS：K8S集群还未拉起，故这里的kubelet是无法启动的，等master初始化时会自动拉起</p><h5 id="部署-k8s-master" tabindex="-1">部署 K8S master <a class="header-anchor" href="#部署-k8s-master" aria-label="Permalink to &quot;部署 K8S master&quot;">​</a></h5><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kubeadm init \\</span></span>
<span class="line"><span>  --apiserver-advertise-address=192.168.56.101 \\</span></span>
<span class="line"><span>  --image-repository registry.aliyuncs.com/google_containers \\</span></span>
<span class="line"><span>  --kubernetes-version v1.18.0 \\</span></span>
<span class="line"><span>  --service-cidr=10.92.0.0/12 \\</span></span>
<span class="line"><span>  --pod-network-cidr=10.220.0.0/16 \\</span></span>
<span class="line"><span>  --ignore-preflight-errors=all</span></span></code></pre></div><ul><li>apiserver-advertise-address 是主节点 IP 地址</li><li><code>service-cidr</code> ：用于 Kubernetes 服务的虚拟 IP 地址（ClusterIP）。当你创建一个服务时，Kubernetes 会自动从这个范围分配一个 IP 地址给服</li><li><code>pod-network-cidr</code>：这个 CIDR 范围用于分配给集群中的 Pods 的 IP 地址。每个 Pod 都会从这个范围内获取一个 IP 地址。</li></ul><p>后面两个地址：这里目前使用的是文档给定的两个地址，具体如何配置的，后面有空再看一下</p><hr><p>部署完成后会获取到 node加入集群的命令以及token</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240414143912.png" alt="image.png"></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kubeadm join 192.168.56.101:6443 --token gdhwj6.hmqvv0wodnh6suwd \\</span></span>
<span class="line"><span>    --discovery-token-ca-cert-hash sha256:3e37e9c89dbe37bd0d3d639f8002545ebca2c083a8d9097c1725f1d7af6a1ede</span></span></code></pre></div><hr><p>使用kubectl命令【如需node节点使用此命令，可使用scp命令分别拷贝config文件至对应目录】</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#创建一个名为 \`.kube\` 的目录。该目录用于存放 \`kubectl\` 的配置文件</span></span>
<span class="line"><span>mkdir -p $HOME/.kube</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#将 Kubernetes 集群的管理员配置文件 \`admin.conf\` 复制到 \`.kube\` 目录，并重命名为 \`config\`。这个配置文件包含了集群的连接信息，包括 API 服务器的地址、认证信息等</span></span>
<span class="line"><span>sudo cp -i /etc/kubernetes/admin.conf $HOME/.kube/config</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#授权</span></span>
<span class="line"><span>sudo chown $(id -u):$(id -g) $HOME/.kube/config</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#列出 Kubernetes 集群中的所有节点</span></span>
<span class="line"><span>$ kubectl get nodes</span></span></code></pre></div><h5 id="加入-k8s-node" tabindex="-1">加入 K8S node <a class="header-anchor" href="#加入-k8s-node" aria-label="Permalink to &quot;加入 K8S node&quot;">​</a></h5><p>在node节点中分别执行，master init后产生的加入命令：</p><p>TIPS：这里加入node后会看到node状态为NotReady，是因为没有安装CNI，kubelet无法通过网络给apiserver上报node状态，安装CNI后即可恢复</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240414144528.png" alt="image.png"></p><h5 id="部署网络插件【cni】" tabindex="-1">部署网络插件【CNI】 <a class="header-anchor" href="#部署网络插件【cni】" aria-label="Permalink to &quot;部署网络插件【CNI】&quot;">​</a></h5><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>wget https://docs.projectcalico.org/manifests/calico.yaml</span></span></code></pre></div><p>下载完成后，修改calico.yaml【定义Pod网络（CALICO_IPV4POOL_CIDR），与前面pod CIDR配置一样即可】</p><p><strong>这里的操作是在主节点下操作</strong>，下载完后，直接在当前目录进行编辑即可，</p><p>需要进行放开注释，并编辑值</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240414145415.png" alt="image.png"></p><p>应用该配置</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># kubectl apply -f calico.yaml</span></span>
<span class="line"><span># kubectl get pods -n kube-system</span></span></code></pre></div><p>这里 <code>kubectl apply -f calico.yaml</code> 会报错：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>error: unable to recognize &quot;calico.yaml&quot;: no matches for kind &quot;PodDisruptionBudget&quot; in version &quot;policy/v1&quot;</span></span></code></pre></div><p>看了一下大家的问题，是因为版本问题导致（这篇文章的时间是 2020 年）</p><p>看一下这个版本对应： <a href="https://blog.csdn.net/qq_32596527/article/details/127692734" target="_blank" rel="noreferrer">https://blog.csdn.net/qq_32596527/article/details/127692734</a></p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240414150322.png" alt="image.png"></p><p>这里的 k8s 版本是 1.18，对应的 calico 版本为 3.18</p><p>解决方案： <a href="https://blog.csdn.net/qq_46237746/article/details/125453966" target="_blank" rel="noreferrer">https://blog.csdn.net/qq_46237746/article/details/125453966</a></p><p>重新下载文件</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>wget https://docs.projectcalico.org/v3.18/manifests/calico.yaml</span></span></code></pre></div><p>重新执行</p><p>应用该配置</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># kubectl apply -f calico.yaml</span></span>
<span class="line"><span># kubectl get pods -n kube-system</span></span></code></pre></div><p>应用后可以看到CNI POD正在初始化中，静待拉起~</p><p>calico running 状态后，查看节点已全部 Ready【需要点时间】</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240414152107.png" alt="image.png"></p><p>到此部署成功。</p><h3 id="使用-kubernetes-部署-mysql-服务" tabindex="-1">使用 Kubernetes 部署 MySQL 服务 <a class="header-anchor" href="#使用-kubernetes-部署-mysql-服务" aria-label="Permalink to &quot;使用 Kubernetes 部署 MySQL 服务&quot;">​</a></h3><p>通过第二节的内容，其实我们也可以看到，k8s 主要还是通过 yaml 文件，通过工具去进行执行相关指令，并进行运行部署容器；</p><p>其中 k8s 主要可以做一些比较高级的工作，但总体来说，对于使用者来说，我们做的工作就是：1、部署 k8s ；2、编写 yaml 文件，将服务放到 k8s 中进行容器编排服务管理</p><p>我们所要关心的，第一点不是负责管理和如何高效处理这个系统的工具或者接口，而是从 POD 开始。</p><p><strong>Pod</strong>：Pod是Kubernetes中的基本部署单元，它是一个或一组容器的集合，共享存储和网络，运行在同一节点上。</p><blockquote><p>Docker Compose 和 Kubernates 的简易区别：</p></blockquote><ul><li>Docker Compose 主要用于开发和测试，或者小型生产环境。</li><li>Kubernetes 用于大规模的生产环境。</li></ul><p>服务搭建</p><p>参考： <a href="https://www.kancloud.cn/zatko/kubernetes_k8s/2290695" target="_blank" rel="noreferrer">https://www.kancloud.cn/zatko/kubernetes_k8s/2290695</a></p><p>master 节点上操作</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#拉取镜像</span></span>
<span class="line"><span>docker pull mysql:5.7</span></span></code></pre></div><p>创建文件</p><p>在<code>/root/docker/mysql</code>目录下创建 mysql-rc.yaml 文件</p><p>mysql-rc.yaml</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apiVersion: v1 # 这是稳定长期使用的 API 版本，具体资源对象的版本可以参考“推荐阅读”</span></span>
<span class="line"><span>kind: ReplicationController # 副本控制器 RC</span></span>
<span class="line"><span>metadata: # 元数据</span></span>
<span class="line"><span>  name: mysql-dev-57 # 定义这个 rc 的名称为 mysql，它具有全局唯一性,5.7 版本，开发环境</span></span>
<span class="line"><span>spec: # 规范</span></span>
<span class="line"><span>  replicas: 1 # pod 副本的期待数量，这里为 1，表示当环境中没有符合条件要求的 pod 数量时需要创建一个，如果符合要求的 pod 数量大于一个就要删除多余的 pod，始终要保持环境中只有一个 pod 符合要求。</span></span>
<span class="line"><span>  selector: # 标签选择器</span></span>
<span class="line"><span>    app: mysql # 符合要求的 pod 都必须要有这个标签 app:mysql</span></span>
<span class="line"><span>  template: # 创建 pod 副本的模板</span></span>
<span class="line"><span>    metadata: # 创建的 pod 副本拥有的元数据</span></span>
<span class="line"><span>      labels: # 创建的 pod 副本的标签</span></span>
<span class="line"><span>        app: mysql # 对应 RC 的标签选择器，保证创建的 pod 副本符合 RC 的选择器范围</span></span>
<span class="line"><span>    spec: # 定义 pod 副本中运行的容器的详细信息</span></span>
<span class="line"><span>      containers: # 容器信息</span></span>
<span class="line"><span>        - name: mysql # 容器的名字</span></span>
<span class="line"><span>          image: mysql:5.7 # 容器中运行的镜像</span></span>
<span class="line"><span>          ports: # 容器对外暴露的端口</span></span>
<span class="line"><span>            - containerPort: 3306 # 容器的端口 3306</span></span>
<span class="line"><span>          env: # 容器中的环境变量</span></span>
<span class="line"><span>            - name: MYSQL_ROOT_PASSWORD # 设置环境变量 MYSQL_ROOT_PASSWORD=&quot;123456&quot;</span></span>
<span class="line"><span>              value: &#39;123456&#39;</span></span></code></pre></div><p>创建服务</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kubectl create -f mysql-rc.yaml</span></span></code></pre></div><p>创建好资源后，查看已经创建的 ReplicationController 资源对象，在命令中可以将其简写为 rc：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kubectl get rc</span></span></code></pre></div><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240414155512.png" alt="image.png"></p><p>在输出中，<code>DESIRED</code>表示这个名为 mysql-dev-57 的 rc 需要创建一个 pod 副本，<code>CURRENT</code>表示当前已经创建好的 pod 副本数量，<code>READY</code>表示 pod 副本已经成功运行，<code>AGE</code>表示存活时间（生命周期）。</p><p>然后查看环境中的 pod，在终端执行如下命令：（等待一段时间后再看，创建需要点时间）</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kubectl get pods</span></span></code></pre></div><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240414155752.png" alt="image.png"></p><p>可以看到使用 rc 创建的 pod 副本的名字为：mysql-dev-57-pqjgm，这个名字是由两部分组成的，前面部分的 mysql-dev-57 和创建它的 rc 名字相同，后面的 pqjgm 是随机生成的字符串可以用来区分由同一个 rc 创建的不同的 pod，READY 为 1/1 表示已经创建好，STATUS 为 Running 表示这个 pod 正处于运行状态。</p><p>当然，我们还可以查看 mysql-dev-57-pqjgm pod 的具体构建过程，如果以后运行不成功，也可以通过 Events 来查看具体是哪里出了问题：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kubectl describe pod mysql-dev-57-pqjgm</span></span></code></pre></div><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240414160049.png" alt="image.png"></p><p>在创建成功运行着 MySQL 的 pod 之后，还需要创建一个与之外应的 Service，这样才能让其它的 pod 可以访问 MySQL 应用提供的服务。</p><p>Service 被创建之后，Kubernetes 会给它分配一个虚拟的 Cluster IP，并且在 Service 的整个生命周期中，这个 Cluster IP 都不会改变，这样的好处就是，pod 可能会随时发生变化（由于某些意外情况被销毁然后重建），但是我们的 Service 始终是确定不变的，</p><p>在 Kubernetes 集群内部通过服务名和暴露出来的端口就可以稳定的访问某一个服务而不需要管隐藏在服务背后的 pod 的变化。</p><p>在<code>/root/docker/mysql</code>目录下新建 <code>mysql-svc.yaml</code> 文件，并向其中写入如下内容：</p><p>mysql-svc.yaml</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apiVersion: v1 # API 版本号，使用稳定版：v1</span></span>
<span class="line"><span>kind: Service # 资源对象类型</span></span>
<span class="line"><span>metadata: # 元数据</span></span>
<span class="line"><span>  name: mysql-dev-57 # Service 的名称为：mysql，这个名称具有全局唯一性</span></span>
<span class="line"><span>spec: # 规范</span></span>
<span class="line"><span>  ports: # 对外暴露出的端口</span></span>
<span class="line"><span>    - port: 3306 # 这里指定为 3306 端口</span></span>
<span class="line"><span>  selector: # 标签选择器</span></span>
<span class="line"><span>    app: mysql # 服务对应的 pod 是具有 app=mysql 标签的这些</span></span></code></pre></div><p>新建服务的 yaml 文件之后执行创建</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kubectl create -f mysql-svc.yaml</span></span></code></pre></div><p>来查看一下创建好的服务，在终端执行如下命令，其中 svc 是 services 的简写</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kubectl get svc</span></span></code></pre></div><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240414160817.png" alt="image.png"></p><p>这里列出了 kubernetes 集群目前全部的服务，第一个名为 kubernetes 的服务是集群启动以后默认创建的服务，</p><p>第二个名为 mysql-dev-57 的服务是我们刚刚创建的，集群自动为它分配了一个 ClusterIP 为 10.90.169.4，它的 3306 端口也是前面在 yaml 文件中已经定义好了的。</p><p>还可以执行如下命令查看 mysql 服务更加详细的信息：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kubectl describe svc mysql-dev-57</span></span></code></pre></div><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240414161113.png" alt="image.png"></p><p>这里有点小坑（应该也不算，实际生产中，的确外部有时候会不允许直接访问）</p><p>这里是 svc 需要设置一下 EXTERNAL-IP</p><p>改一下 mysql-svc.yaml</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apiVersion: v1 # API 版本号，使用稳定版：v1</span></span>
<span class="line"><span>kind: Service # 资源对象类型</span></span>
<span class="line"><span>metadata: # 元数据</span></span>
<span class="line"><span>  name: mysql-dev-57 # Service 的名称为：mysql，这个名称具有全局唯一性</span></span>
<span class="line"><span>spec: # 规范</span></span>
<span class="line"><span>  ports: # 对外暴露出的端口</span></span>
<span class="line"><span>    - port: 3306 # 这里指定为 3306 端口</span></span>
<span class="line"><span>      targetPort: 3306</span></span>
<span class="line"><span>  selector: # 标签选择器</span></span>
<span class="line"><span>    app: mysql # 服务对应的 pod 是具有 app=mysql 标签的这些</span></span>
<span class="line"><span>  externalIPs:</span></span>
<span class="line"><span>    - 192.168.56.101</span></span></code></pre></div><p>执行命令</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kubectl apply -f mysql-svc.yaml</span></span></code></pre></div><ul><li><code>kubectl apply</code> 命令会比较已经存在的资源配置和新的配置文件，然后计算出需要更新的差异，并应用这些差异来更新资源。这种方式非常适合持续集成和持续部署（CI/CD）流程。</li></ul><p>至此，这里的外部服务连接也是 OK的。</p><hr><h3 id="关停-k8s-操作" tabindex="-1">关停 k8s 操作 <a class="header-anchor" href="#关停-k8s-操作" aria-label="Permalink to &quot;关停 k8s 操作&quot;">​</a></h3><p>参考： <a href="https://blog.51cto.com/u_14568336/9719914" target="_blank" rel="noreferrer">https://blog.51cto.com/u_14568336/9719914</a></p><p>未实际操作，这里记录一下</p><p>停止K8S集群流程</p><table tabindex="0"><thead><tr><th>步骤</th><th>操作</th></tr></thead><tbody><tr><td>1</td><td>清空Kubernetes资源</td></tr><tr><td>2</td><td>删除Pod</td></tr><tr><td>3</td><td>删除Service</td></tr><tr><td>4</td><td>关闭Kubelet服务</td></tr><tr><td>5</td><td>删除Master节点</td></tr><tr><td>6</td><td>停止K8S集群</td></tr></tbody></table><p>首先，我们需要清空Kubernetes中的所有资源，包括Deployment、StatefulSet、Service等等。这可以通过kubectl命令来实现。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kubectl delete deployment --all</span></span>
<span class="line"><span>kubectl delete statefulset --all</span></span>
<span class="line"><span>kubectl delete service --all</span></span></code></pre></div><p>接着，我们需要删除当前所有的Pod。同样可以使用kubectl命令来删除。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kubectl delete pods --all</span></span></code></pre></div><p>删除Service资源，同样使用kubectl命令。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kubectl delete service --all</span></span></code></pre></div><p>关闭Kubelet服务，可以通过systemctl命令来停止。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo systemctl stop kubelet</span></span></code></pre></div><p>将Master节点从集群中移出，执行命令前请确保备份数据。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kubeadm reset</span></span></code></pre></div><p>最后，停止整个Kubernetes集群。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo kubeadm reset</span></span></code></pre></div>`,207)])])}const b=a(l,[["render",t]]);export{h as __pageData,b as default};
